flowDot:
digraph G {
  rankdir=TB; bgcolor="transparent"; nodesep=0.35; ranksep=0.5; newrank=true;
  node [fontname="Helvetica", fontsize=18, style="rounded,filled", penwidth=2, margin="0.2,0.1"];
  edge [fontname="Helvetica", fontsize=16, color="#6B7280", penwidth=1.5];
  Q [label="User question", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  COORD [label="⭐ Coordinator\ndecompose · pick subagents", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  GATE [label="⭐ Task tool in\nallowedTools?", shape=diamond, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  FAN [label="⭐ Task calls\n(parallel: ONE response)", shape=box, style="rounded,filled", fillcolor="#EDE9FE", color="#7C3AED"];
  CTX [label="⭐ Complete context in\nthe PROMPT (+ sources)", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  SEARCH [label="Search subagents\n(isolated context)", shape=box, style="rounded,filled", fillcolor="#D1FAE5", color="#059669"];
  ANALYZE [label="Analysis subagent", shape=box, style="rounded,filled", fillcolor="#D1FAE5", color="#059669"];
  SYNTH [label="Synthesis subagent", shape=box, style="rounded,filled", fillcolor="#D1FAE5", color="#059669"];
  BACK [label="Only the final message\nreturns to the coordinator", shape=box, style="rounded,filled", fillcolor="#FEF3C7", color="#D97706"];
  REVIEW [label="⭐ Coordinator reviews\ncoverage & gaps", shape=box, style="rounded,filled", fillcolor="#CCFBF1", color="#0D9488"];
  DONE [label="Cited report", shape=box, style="rounded,filled", fillcolor="#DBEAFE", color="#0066CC"];
  NOTASK [label="✗ Task not in\nallowedTools", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  INHERIT [label="✗ assumes inherited /\nshared context", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  FIXED [label="✗ hard-coded pipeline\nfor every question", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NARROW [label="✗ too-narrow\ndecomposition", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  SEQ [label="✗ one Task call\nper turn", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  PEER [label="✗ results routed around\nthe coordinator", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  NOREVIEW [label="✗ no gap review,\nno re-delegation", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  BLOAT [label="✗ whole transcripts\nreturned", shape=box, style="rounded,filled,dashed", fillcolor="#FFFFFF", color="#DC2626"];
  Q -> COORD -> GATE -> FAN -> CTX -> SEARCH -> ANALYZE -> SYNTH -> BACK -> REVIEW -> DONE;
  REVIEW -> FAN [constraint=false, label="re-delegate", color="#0D9488", fontcolor="#0D9488"];
  { rank=same; NOTASK; INHERIT; }
  { rank=same; FIXED; NARROW; }
  { rank=same; SEQ; PEER; }
  { rank=same; NOREVIEW; BLOAT; }
  DONE -> NOTASK -> FIXED -> SEQ -> NOREVIEW [style=invis];
  KEY [shape=plain, label=<<TABLE BORDER="0" CELLBORDER="1" CELLSPACING="3" CELLPADDING="3"><TR><TD COLSPAN="2" BORDER="0" ALIGN="LEFT"><FONT POINT-SIZE="18"><B>Key</B></FONT></TD></TR><TR><TD BGCOLOR="#DBEAFE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">coordinator (hub)</FONT></TD></TR><TR><TD BGCOLOR="#EDE9FE" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">spawning — Task tool / Task calls</FONT></TD></TR><TR><TD BGCOLOR="#FEF3C7" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">context passing (prompt in, final message out)</FONT></TD></TR><TR><TD BGCOLOR="#D1FAE5" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">subagent work (isolated context)</FONT></TD></TR><TR><TD BGCOLOR="#CCFBF1" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">coverage review & re-delegation</FONT></TD></TR><TR><TD BGCOLOR="#FFFFFF" WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">bug (an exam distractor)</FONT></TD></TR><TR><TD WIDTH="26" FIXEDSIZE="TRUE" HEIGHT="20"><FONT POINT-SIZE="16">⭐</FONT></TD><TD ALIGN="LEFT" BORDER="0"><FONT POINT-SIZE="16">named by the exam guide (TS 1.2 pp.5–6, TS 1.3 pp.6–7)</FONT></TD></TR></TABLE>>];
  NOREVIEW -> KEY [style=invis];
}

decisionDot:
digraph D {
  rankdir=TB; bgcolor="transparent"; nodesep=0.4; ranksep=0.45;
  node [fontname="Helvetica", fontsize=11, style="rounded,filled", fillcolor="#F3F4F6", color="#9CA3AF", penwidth=1.5];
  edge [fontname="Helvetica", fontsize=10, color="#6B7280"];
  Q1 [shape=diamond, label="Does the task split into\nindependent parts?"];
  ONE [shape=box, label="One agent\n(or one subagent to keep noisy\nwork out of the main context)"];
  Q2 [shape=diamond, label="Do the parts need each\nother's results?"];
  PAR [shape=box, fillcolor="#EDE9FE", color="#7C3AED", label="Spawn them together:\nseveral Task calls in ONE response\n(guide TS 1.3, Skill 3)"];
  SEQ [shape=box, fillcolor="#DBEAFE", color="#0066CC", label="Chain them THROUGH the coordinator:\nresult -> coordinator -> next prompt\n(guide TS 1.2, Skill 4)"];
  Q3 [shape=diamond, label="Does each subagent's prompt\ncarry everything it needs?"];
  CTX [shape=box, fillcolor="#FEF3C7", color="#D97706", label="Add the complete findings + sources\nto the prompt (guide TS 1.3, Skills 1-2)"];
  Q4 [shape=diamond, label="Can coverage be checked\nagainst criteria?"];
  REV [shape=box, fillcolor="#CCFBF1", color="#0D9488", label="Coordinator reviews the draft, re-delegates\ntargeted searches, re-synthesises\n(guide TS 1.2, Skill 3)"];
  Q1 -> ONE [label="no"]; Q1 -> Q2 [label="yes"];
  Q2 -> PAR [label="no"]; Q2 -> SEQ [label="yes"];
  PAR -> Q3; SEQ -> Q3;
  Q3 -> CTX [label="no"]; Q3 -> Q4 [label="yes"]; CTX -> Q4;
  Q4 -> REV [label="yes"];
}
